import sys

data = sys.stdin.read().split()
n = int(data[0])
p = [int(x) for x in data[1:1 + n]]
# F[x]: best profit from trades whose cooldown has fully ended by day x (so a buy on day x is allowed)
F = [0] * (n + 1)
for x in range(n + 1):
    best = 0
    for b in range(n):
        for s in range(b + 1, n):
            if 2 * s - b + 2 <= x and b < x:
                best = max(best, F[b] + p[s] - p[b])
    F[x] = best
ans = 0
for b in range(n):
    for s in range(b + 1, n):
        ans = max(ans, F[b] + p[s] - p[b])
print(ans)

