def gen(rng):
    def fmt(a):
        return str(len(a)) + "\n" + " ".join(map(str, a))
    tests = [
        fmt([5]), fmt([1, 2]), fmt([2, 1]), fmt([5, 4, 3, 2, 1]), fmt([1, 2, 3, 4, 5]),
        fmt([1, 5, 1, 5, 1, 5]), fmt([3, 3, 3, 3]), fmt([1, 10, 1, 1, 1, 10]),
        fmt([1, 5, 1, 1, 5, 1, 1, 1, 5]), fmt([10 ** 9, 1, 10 ** 9, 1, 10 ** 9]),
    ]
    for n in (3, 4, 5, 6, 7, 8, 10, 12, 15, 20, 30):
        for _ in range(3):
            hi = rng.choice([3, 9, 30])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 2000
    tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 100) for _ in range(N)]))
    tests.append(fmt([1 + (i % 7) * 3 + rng.randint(0, 2) for i in range(N)]))
    tests.append(fmt([(i // 2) % 2 * 10 ** 8 + rng.randint(1, 1000) for i in range(N)]))
    tests.append(fmt([i + 1 for i in range(N)]))
    return tests

